// ---------------------------------------------------------
// MINI GENERADOR DE PDF
// Texto (Helvetica normal y negrita), rectángulos y líneas.
// Las coordenadas se dan desde la esquina superior izquierda.
// ---------------------------------------------------------

const PDF_WIDTHS = {
    normal: [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,556,556,333,500,278,556,500,722,500,500,500,334,260,334,584],
    bold: [278,333,474,556,556,889,722,238,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,333,333,584,584,584,611,975,722,722,722,722,667,611,778,722,278,556,722,611,833,722,778,667,778,722,667,611,722,667,944,667,667,611,333,278,333,584,556,333,556,611,556,611,556,333,611,611,278,278,556,278,889,611,611,611,611,389,556,333,611,556,778,556,556,500,389,280,389,584]
};

// Caracteres especiales de WinAnsi que usamos
const PDF_SPECIAL = { "•": [149, 350], "·": [183, 278], "º": [186, 365], "ª": [170, 370], "¿": [191, 611], "¡": [161, 333], "°": [176, 400] };

// Firma de la Gerencia de Operaciones (Ronny M.)
// JPEG en escala de grises para el PDF y PNG transparente para la vista previa
const SIGNATURE = {
    width: 520,
    height: 175,
    jpeg: "",
    png: "data:image/png;base64,"
};

class MiniPDF {

    constructor() {
        this.width = 595.28;   // A4
        this.height = 841.89;
        this.pages = [];
        this.images = {};
        this.font = "normal";
        this.size = 10;
        this.addPage();
    }

    addPage() {
        this.page = [];
        this.pages.push(this.page);
        return this;
    }

    // Convierte el texto a bytes WinAnsi (acepta tildes y ñ)
    encode(text) {
        let out = "";
        for (const char of String(text ?? "")) {
            const fixed = char === "−" || char === "–" ? "-" : char;
            const code = fixed.charCodeAt(0);
            if (PDF_SPECIAL[fixed]) out += String.fromCharCode(PDF_SPECIAL[fixed][0]);
            else if (code >= 32 && code <= 126) out += fixed;
            else if (code >= 160 && code <= 255) out += fixed;
            else out += "?";
        }
        return out.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
    }

    charWidth(char, bold) {
        const table = bold ? PDF_WIDTHS.bold : PDF_WIDTHS.normal;
        if (PDF_SPECIAL[char]) return PDF_SPECIAL[char][1];
        const base = char.normalize("NFD")[0];
        const code = base.charCodeAt(0);
        return code >= 32 && code <= 126 ? table[code - 32] : 556;
    }

    textWidth(text, size = this.size, bold = this.font === "bold") {
        let total = 0;
        for (const char of String(text ?? "")) total += this.charWidth(char, bold);
        return (total * size) / 1000;
    }

    // Corta un texto largo para que quepa en un ancho
    fit(text, maxWidth, size = this.size, bold = this.font === "bold") {
        let value = String(text ?? "");
        if (this.textWidth(value, size, bold) <= maxWidth) return value;
        while (value.length && this.textWidth(value + "...", size, bold) > maxWidth) value = value.slice(0, -1);
        return value.trimEnd() + "...";
    }

    rgb(hex) {
        const value = hex.replace("#", "");
        return [0, 2, 4].map(i => (parseInt(value.slice(i, i + 2), 16) / 255).toFixed(3)).join(" ");
    }

    setFont(bold = false, size = 10) {
        this.font = bold ? "bold" : "normal";
        this.size = size;
        return this;
    }

    text(value, x, y, { color = "#26474E", align = "left", bold, size } = {}) {
        if (bold !== undefined) this.font = bold ? "bold" : "normal";
        if (size !== undefined) this.size = size;

        const width = this.textWidth(value);
        const left = align === "right" ? x - width : align === "center" ? x - width / 2 : x;
        const font = this.font === "bold" ? "F2" : "F1";

        this.page.push(`BT ${this.rgb(color)} rg /${font} ${this.size} Tf ${left.toFixed(2)} ${(this.height - y).toFixed(2)} Td (${this.encode(value)}) Tj ET`);
        return this;
    }

    rect(x, y, w, h, fill, stroke) {
        const box = `${x.toFixed(2)} ${(this.height - y - h).toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re`;
        if (fill && stroke) this.page.push(`${this.rgb(fill)} rg ${this.rgb(stroke)} RG 0.8 w ${box} B`);
        else if (fill) this.page.push(`${this.rgb(fill)} rg ${box} f`);
        else if (stroke) this.page.push(`${this.rgb(stroke)} RG 0.8 w ${box} S`);
        return this;
    }

    line(x1, y1, x2, y2, color = "#DCE8E9", width = 0.8) {
        this.page.push(`${this.rgb(color)} RG ${width} w ${x1.toFixed(2)} ${(this.height - y1).toFixed(2)} m ${x2.toFixed(2)} ${(this.height - y2).toFixed(2)} l S`);
        return this;
    }

    // Dibuja una imagen JPEG en escala de grises (base64)
    image(name, base64, pixelWidth, pixelHeight, x, y, w, h) {
        if (!this.images[name]) this.images[name] = { data: atob(base64), width: pixelWidth, height: pixelHeight };
        this.page.push(`q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${x.toFixed(2)} ${(this.height - y - h).toFixed(2)} cm /${name} Do Q`);
        return this;
    }

    // Arma el archivo PDF
    output() {
        const objects = [];
        const add = body => objects.push(body) && objects.length;

        const catalog = add("");   // se completa después
        const pagesRef = add("");
        const fontNormal = add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
        const fontBold = add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");

        const xobjects = Object.entries(this.images).map(([name, img]) =>
            `/${name} ${add(`<< /Type /XObject /Subtype /Image /Width ${img.width} /Height ${img.height} /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /DCTDecode /Length ${img.data.length} >>\nstream\n${img.data}\nendstream`)} 0 R`);
        const xobjectRes = xobjects.length ? ` /XObject << ${xobjects.join(" ")} >>` : "";

        const kids = this.pages.map(page => {
            const stream = page.join("\n");
            const content = add(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);
            return add(`<< /Type /Page /Parent ${pagesRef} 0 R /MediaBox [0 0 ${this.width} ${this.height}] /Resources << /Font << /F1 ${fontNormal} 0 R /F2 ${fontBold} 0 R >>${xobjectRes} >> /Contents ${content} 0 R >>`);
        });

        objects[catalog - 1] = `<< /Type /Catalog /Pages ${pagesRef} 0 R >>`;
        objects[pagesRef - 1] = `<< /Type /Pages /Kids [${kids.map(id => `${id} 0 R`).join(" ")}] /Count ${kids.length} >>`;

        let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
        const offsets = [];

        objects.forEach((body, index) => {
            offsets.push(pdf.length);
            pdf += `${index + 1} 0 obj\n${body}\nendobj\n`;
        });

        const xref = pdf.length;
        pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
        offsets.forEach(offset => { pdf += `${String(offset).padStart(10, "0")} 00000 n \n`; });
        pdf += `trailer\n<< /Size ${objects.length + 1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;

        const bytes = new Uint8Array(pdf.length);
        for (let i = 0; i < pdf.length; i++) bytes[i] = pdf.charCodeAt(i) & 0xff;
        return new Blob([bytes], { type: "application/pdf" });
    }

    save(filename) {
        const url = URL.createObjectURL(this.output());
        const link = document.createElement("a");
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 2000);
    }
}


// ---------------------------------------------------------
// PIEZAS COMUNES DEL DISEÑO
// ---------------------------------------------------------

const PDF_COLORS = {
    dark: "#26474E",
    primary: "#2CCED2",
    pale: "#B9EDED",
    soft: "#E8F8F8",
    text: "#3D5A60",
    muted: "#7C9296",
    border: "#DCE8E9",
    green: "#137C81",
    red: "#C23B3B",
    white: "#FFFFFF"
};

function pdfHeader(pdf, title, subtitle) {
    const c = PDF_COLORS;

    pdf.rect(0, 0, pdf.width, 108, c.dark);
    pdf.rect(0, 108, pdf.width, 4, c.primary);

    // Logo
    pdf.rect(48, 34, 34, 34, c.primary);
    pdf.text("B", 65, 58, { color: c.dark, bold: true, size: 19, align: "center" });
    pdf.text("banklite", 92, 57, { color: c.white, bold: true, size: 19 });

    pdf.text(title, pdf.width - 48, 50, { color: c.white, bold: true, size: 15, align: "right" });
    pdf.text(subtitle, pdf.width - 48, 68, { color: c.pale, bold: false, size: 9.5, align: "right" });
}

function pdfFooter(pdf, index, total) {
    const c = PDF_COLORS;
    const y = pdf.height - 40;

    pdf.line(48, y - 14, pdf.width - 48, y - 14, c.border);
    pdf.text("Banklite · Tu dinero. Tu control.", 48, y, { color: c.muted, bold: false, size: 8 });
    pdf.text(`Generado el ${formatDate(new Date(), { dateStyle: "long", timeStyle: "short" })}`, pdf.width / 2, y, { color: c.muted, size: 8, align: "center" });
    pdf.text(`Página ${index} de ${total}`, pdf.width - 48, y, { color: c.muted, size: 8, align: "right" });
}

// Firma manuscrita encima de la línea de "Gerencia de Operaciones"
function pdfSignature(pdf, lineY) {
    const w = 150;
    const h = w * SIGNATURE.height / SIGNATURE.width;
    pdf.image("ImSig", SIGNATURE.jpeg, SIGNATURE.width, SIGNATURE.height, 52, lineY - h + 8, w, h);
}

function pdfFinish(pdf, filename) {
    const total = pdf.pages.length;
    pdf.pages.forEach((page, index) => {
        pdf.page = page;
        pdfFooter(pdf, index + 1, total);
    });
    pdf.save(filename);
}

// Formato de dinero para los PDF (los datos llegan del ledger con su moneda).
function pdfMoney(value, currency = "COP") {
    return new Intl.NumberFormat("es-CO", {
        style: "currency",
        currency,
        maximumFractionDigits: currency === "COP" ? 0 : 2
    }).format(Number(value) || 0);
}

// Las transferencias a otros bancos son cargos hacia la cuenta de compensación.
function movementTypeLabel(movement) {
    if (movement.type === "debit" && /^Transferencia a /.test(movement.description || "")) return "Transferencia a otro banco";
    return MOVEMENT_TYPES[movement.type] || "Movimiento";
}

const MOVEMENT_TYPES = {
    transfer: "Transferencia",
    deposit: "Consignación",
    credit: "Abono",
    debit: "Cargo",
    reversal: "Reverso",
    payment: "Pago a comercio",
    reward: "Canje de puntos",
    saving: "Ahorro e inversión"
};


// ---------------------------------------------------------
// COMPROBANTE DE UNA OPERACIÓN
// movement: movimiento real del ledger { transactionId, type, direction,
//   amount, currency, description, counterpartyAccountLast4, createdAt }
// holder: { name, accountType, accountNumber }
// ---------------------------------------------------------

function downloadReceipt(movement, holder) {

    if (!movement) return;

    const c = PDF_COLORS;
    const pdf = new MiniPDF();
    const incoming = movement.direction === "in";
    const isTransfer = movement.type === "transfer" || movementTypeLabel(movement) === "Transferencia a otro banco";
    const number = String(movement.transactionId || movement.id || "").toUpperCase();
    const shortNumber = number.slice(0, 8);
    const amountText = pdfMoney(movement.amount, movement.currency);

    pdfHeader(pdf, isTransfer ? "Comprobante de transferencia" : "Comprobante de operación", `N.º ${shortNumber}`);

    // Monto destacado
    let y = 150;
    pdf.text(isTransfer ? (incoming ? "Valor recibido" : "Valor enviado") : "Valor de la operación", pdf.width / 2, y, { color: c.muted, bold: false, size: 10, align: "center" });
    pdf.text(amountText, pdf.width / 2, y + 34, { color: c.dark, bold: true, size: 30, align: "center" });

    const status = "APROBADA";
    const statusWidth = pdf.textWidth(status, 9, true) + 26;
    pdf.rect(pdf.width / 2 - statusWidth / 2, y + 48, statusWidth, 20, c.soft);
    pdf.text(status, pdf.width / 2, y + 62, { color: c.green, bold: true, size: 9, align: "center" });

    const ownAccount = `${holder.accountType} ···· ${String(holder.accountNumber || "").slice(-4)}`;
    const counterparty = movement.counterpartyAccountLast4
        ? `${movement.type === "payment" ? "Comercio" : "Cuenta Banklite"} ···· ${movement.counterpartyAccountLast4}`
        : "—";
    const rows = [
        ["Fecha y hora", formatDate(movement.createdAt, { dateStyle: "long", timeStyle: "short" })],
        ["Tipo", movementTypeLabel(movement)],
        ["Descripción", movement.description || "—"],
        ["Movimiento", `${incoming ? "+" : "-"}${amountText}`],
        (isTransfer && movement.counterpartyAccountLast4) || movement.type === "payment" ? [incoming ? "Cuenta de origen" : "Cuenta de destino", counterparty] : null,
        [incoming ? "Cuenta que recibe" : "Cuenta de origen", ownAccount],
        ["Titular", holder.name],
        ["Número de operación", number]
    ].filter(Boolean);

    y = 262;
    const left = 70;
    const right = pdf.width - 70;

    pdf.rect(48, y - 22, pdf.width - 96, rows.length * 34 + 52, "#F8FBFB", c.border);
    pdf.text("Detalle de la operación", left, y, { color: c.dark, bold: true, size: 11 });
    y += 14;

    rows.forEach(([label, value], index) => {
        y += 34;
        if (index > 0) pdf.line(left, y - 22, right, y - 22, c.border);
        pdf.text(label, left, y - 4, { color: c.muted, bold: false, size: 9.5 });
        pdf.text(pdf.fit(value, 300, 10, true), right, y - 4, { color: c.dark, bold: true, size: 10, align: "right" });
    });

    y += 44;
    pdf.text("Conserva este comprobante como soporte de tu operación.", pdf.width / 2, y, { color: c.text, bold: false, size: 9, align: "center" });
    pdf.text("Banklite nunca te pedirá tu clave por teléfono, correo o mensaje.", pdf.width / 2, y + 15, { color: c.muted, size: 8.5, align: "center" });

    pdfFinish(pdf, `comprobante-${shortNumber}.pdf`);
}


// ---------------------------------------------------------
// EXTRACTO DEL MES
// statement: respuesta de GET /ledger/accounts/:id/statement
//   { from, to, currency, openingBalance, totalIn, totalOut,
//     closingBalance, movementCount, truncated, movements (más antiguo primero) }
// holder: { name, document, accountType, accountNumber }
// label: "Octubre 2026"
// ---------------------------------------------------------

function downloadStatement(statement, holder, label, fileKey) {

    const c = PDF_COLORS;
    const money = value => pdfMoney(value, statement.currency);
    const movements = statement.movements || [];
    const pdf = new MiniPDF();

    pdfHeader(pdf, "Extracto de cuenta", `Periodo: ${label.toLowerCase()}`);

    let y = 146;
    [
        ["Titular", holder.name],
        ["Documento", holder.document],
        ["Producto", `${holder.accountType} · ${statement.currency}`],
        ["Número de cuenta", holder.accountNumber]
    ].forEach(([title, value], index) => {
        const x = 48 + (index % 2) * 255;
        const rowY = y + Math.floor(index / 2) * 36;
        pdf.text(title.toUpperCase(), x, rowY, { color: c.muted, bold: true, size: 7.5 });
        pdf.text(pdf.fit(value, 240, 11, true), x, rowY + 15, { color: c.dark, bold: true, size: 11 });
    });

    y = 236;
    const boxes = [
        ["Saldo inicial", money(statement.openingBalance), c.dark],
        ["Entradas", "+" + money(statement.totalIn), c.green],
        ["Salidas", "-" + money(statement.totalOut), c.red],
        ["Saldo final", money(statement.closingBalance), c.dark]
    ];
    const boxWidth = (pdf.width - 96 - 30) / 4;
    boxes.forEach(([title, value, color], index) => {
        const x = 48 + index * (boxWidth + 10);
        const highlight = index === 3;
        pdf.rect(x, y, boxWidth, 56, highlight ? c.soft : "#F8FBFB", highlight ? c.pale : c.border);
        pdf.text(title, x + 12, y + 20, { color: c.muted, bold: false, size: 8.5 });
        pdf.text(pdf.fit(value, boxWidth - 20, 12, true), x + 12, y + 41, { color, bold: true, size: 12 });
    });

    const cols = { date: 48, desc: 118, value: 438, balance: pdf.width - 48 };
    const tableHeader = top => {
        pdf.rect(48, top, pdf.width - 96, 24, c.dark);
        pdf.text("FECHA", cols.date + 8, top + 16, { color: c.white, bold: true, size: 8 });
        pdf.text("DESCRIPCIÓN", cols.desc, top + 16, { color: c.white, bold: true, size: 8 });
        pdf.text("VALOR", cols.value, top + 16, { color: c.white, bold: true, size: 8, align: "right" });
        pdf.text("SALDO", cols.balance - 8, top + 16, { color: c.white, bold: true, size: 8, align: "right" });
        return top + 24;
    };

    y = 316;
    pdf.text(`Movimientos del periodo (${statement.movementCount})`, 48, y, { color: c.dark, bold: true, size: 11 });
    y = tableHeader(y + 10);

    pdf.rect(48, y, pdf.width - 96, 26, "#F8FBFB");
    pdf.text("Saldo inicial del periodo", cols.desc, y + 17, { color: c.muted, bold: false, size: 8.5 });
    pdf.text(money(statement.openingBalance), cols.balance - 8, y + 17, { color: c.dark, bold: true, size: 8.5, align: "right" });
    y += 26;

    let running = Number(statement.openingBalance) || 0;
    const bottom = pdf.height - 80;

    if (!movements.length) {
        y += 30;
        pdf.text("No hubo movimientos en este periodo.", pdf.width / 2, y, { color: c.muted, bold: false, size: 10, align: "center" });
    }

    movements.forEach((movement, index) => {
        if (y + 34 > bottom) {
            pdf.addPage();
            pdfHeader(pdf, "Extracto de cuenta", `${label} · continuación`);
            y = tableHeader(140);
        }
        const signed = (movement.direction === "in" ? 1 : -1) * (Number(movement.amount) || 0);
        running += signed;

        if (index % 2 === 1) pdf.rect(48, y, pdf.width - 96, 34, "#FAFCFC");
        pdf.line(48, y + 34, pdf.width - 48, y + 34, c.border, 0.5);

        const date = new Date(movement.createdAt);
        pdf.text(formatDate(date, { day: "2-digit", month: "2-digit" }), cols.date + 8, y + 14, { color: c.text, bold: false, size: 8.5 });
        pdf.text(formatDate(date, { hour: "2-digit", minute: "2-digit" }), cols.date + 8, y + 26, { color: c.muted, size: 7.5 });

        const detail = [movementTypeLabel(movement), movement.counterpartyAccountLast4 ? `Cuenta ···· ${movement.counterpartyAccountLast4}` : ""].filter(Boolean).join(" · ");
        pdf.text(pdf.fit(movement.description || "Movimiento", 230, 9, true), cols.desc, y + 14, { color: c.dark, bold: true, size: 9 });
        pdf.text(pdf.fit(detail, 230, 7.5, false), cols.desc, y + 26, { color: c.muted, bold: false, size: 7.5 });

        pdf.text(`${signed >= 0 ? "+" : "-"}${money(Math.abs(signed))}`, cols.value, y + 18, { color: signed >= 0 ? c.green : c.red, bold: true, size: 9, align: "right" });
        pdf.text(money(running), cols.balance - 8, y + 18, { color: c.dark, bold: false, size: 9, align: "right" });
        y += 34;
    });

    if (y + 50 > pdf.height - 64) {
        pdf.addPage();
        pdfHeader(pdf, "Extracto de cuenta", `${label} · continuación`);
        y = 140;
    }

    y += 14;
    pdf.rect(48, y, pdf.width - 96, 30, c.soft);
    pdf.text("Saldo final del periodo", cols.desc, y + 19, { color: c.dark, bold: true, size: 9.5 });
    pdf.text(money(statement.closingBalance), cols.balance - 8, y + 19, { color: c.dark, bold: true, size: 10, align: "right" });

    const note = statement.truncated
        ? `El periodo tiene ${statement.movementCount} movimientos; este extracto muestra los primeros ${movements.length}. Los totales y saldos sí incluyen todos.`
        : "Si encuentras alguna operación que no reconoces, comunícate con Banklite.";
    pdf.text(note, 48, y + 56, { color: c.muted, bold: false, size: 8.5 });

    pdfFinish(pdf, `extracto-banklite-${fileKey}.pdf`);
}


function pdfWrap(pdf, text, maxWidth, size, bold = false) {
    const lines = [];
    let line = "";
    String(text).split(" ").forEach(word => {
        const test = line ? `${line} ${word}` : word;
        if (pdf.textWidth(test, size, bold) > maxWidth && line) {
            lines.push(line);
            line = word;
        } else {
            line = test;
        }
    });
    if (line) lines.push(line);
    return lines;
}

// ---------------------------------------------------------
// CERTIFICADO DE CUENTA (certificación bancaria)
// ---------------------------------------------------------

// info: datos reales de la cuenta y del titular (los arma dashboard.js con /accounts, /ledger y /kyc).
function downloadAccountCertificate(info, includeBalance, code) {
    const c = PDF_COLORS;
    const pdf = new MiniPDF();
    const today = formatDate(new Date(), { dateStyle: "long" });

    pdfHeader(pdf, "Certificado de cuenta", "Certificación bancaria");

    let y = 160;
    pdf.text("A QUIEN INTERESE", 48, y, { color: c.dark, bold: true, size: 12 });
    y += 26;

    const intro = `Banklite certifica que ${info.name}, identificado(a) con ${info.document}, es titular del producto que se describe a continuación, cuyo estado a la fecha de expedición de este documento es: ${info.status.toLowerCase()}.`;
    pdfWrap(pdf, intro, pdf.width - 96, 10).forEach(line => {
        pdf.text(line, 48, y, { color: c.text, bold: false, size: 10 });
        y += 15;
    });

    y += 16;
    pdf.rect(48, y, pdf.width - 96, 24, c.dark);
    pdf.text("DATOS DEL PRODUCTO", 60, y + 16, { color: c.white, bold: true, size: 8.5 });
    y += 24;

    const rows = [
        ["Titular", info.name],
        ["Documento de identidad", info.document],
        ["Producto", info.accountType],
        ["Número de cuenta", info.accountFormatted],
        ["Estado", info.status],
        ["Fecha de apertura", formatDate(info.opened, { dateStyle: "long" })],
        ["Moneda", info.currency]
    ];
    if (includeBalance) rows.push(["Saldo disponible a la fecha", info.balance]);

    rows.forEach(([label, value], index) => {
        if (index % 2 === 1) pdf.rect(48, y, pdf.width - 96, 24, "#F8FBFB");
        pdf.text(label, 60, y + 16, { color: c.muted, bold: false, size: 9.5 });
        pdf.text(pdf.fit(value, 300, 10, true), pdf.width - 60, y + 16, { color: c.dark, bold: true, size: 10, align: "right" });
        pdf.line(48, y + 24, pdf.width - 48, y + 24, c.border, 0.5);
        y += 24;
    });

    y += 22;
    const closing = `La presente certificación se expide a solicitud del titular el ${today}${includeBalance ? "" : " y no incluye información de saldos"}.`;
    pdfWrap(pdf, closing, pdf.width - 96, 10).forEach(line => {
        pdf.text(line, 48, y, { color: c.text, bold: false, size: 10 });
        y += 15;
    });

    y += 8;
    pdfWrap(pdf, "• Documento de ejemplo de un proyecto académico. No tiene validez ante ninguna entidad.", pdf.width - 96, 8.5).forEach(line => {
        pdf.text(line, 48, y, { color: c.muted, bold: false, size: 8.5 });
        y += 12;
    });

    y += 40;
    pdfSignature(pdf, y);
    pdf.line(48, y, 230, y, c.dark, 0.8);
    pdf.text("Gerencia de Operaciones", 48, y + 14, { color: c.dark, bold: true, size: 9 });
    pdf.text("Banklite", 48, y + 26, { color: c.muted, bold: false, size: 8.5 });
    pdf.text("Código de verificación", pdf.width - 48, y + 2, { color: c.muted, bold: false, size: 8, align: "right" });
    pdf.text(code, pdf.width - 48, y + 18, { color: c.dark, bold: true, size: 10, align: "right" });

    pdfFinish(pdf, `certificado-cuenta-${info.account.slice(-4)}.pdf`);
}

